"use client";

import { useRouter } from "next/navigation";
import { useCallback, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { isFirebaseConfigured } from "@/lib/firebase";
import { setAuthenticated } from "@/lib/authSession";
import {
  DEMO_GOOGLE_EMAIL,
  saveAccountEmail,
} from "@/lib/profileStorage";
import { signInWithGoogle } from "@/services/authService";
import {
  getUserProfile,
  hasCompletedProfile,
} from "@/services/userProfileService";
import { getAuthErrorMessage } from "@/utils/authErrors";

export type GoogleAuthIntent = "signin" | "signup";

async function handleDemoGoogleAuth(
  intent: GoogleAuthIntent,
  router: ReturnType<typeof useRouter>,
) {
  saveAccountEmail(DEMO_GOOGLE_EMAIL);
  if (typeof window !== "undefined") {
    window.localStorage.setItem("carechain_user_name", "Alex");
    window.localStorage.setItem("carechain_auth_provider", "google");
  }
  setAuthenticated("Alex");

  const completed = window.localStorage.getItem("carechain_demo_profile_complete");
  if (!completed) {
    router.replace("/signup?complete=1&demo=1");
    return;
  }

  router.replace("/");
}

export function useGoogleAuth(intent: GoogleAuthIntent = "signin") {
  const router = useRouter();
  const { refreshProfile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const signInWithGoogleAccount = useCallback(async () => {
    setLoading(true);
    setError(null);

    if (!isFirebaseConfigured) {
      try {
        await handleDemoGoogleAuth(intent, router);
      } catch (err) {
        setError(getAuthErrorMessage(err));
      } finally {
        setLoading(false);
      }
      return;
    }

    try {
      const user = await signInWithGoogle();
      const profile = await getUserProfile(user.uid);
      await refreshProfile();

      const name =
        profile?.fullName?.split(/\s+/)[0] ??
        user.displayName?.split(/\s+/)[0] ??
        "Alex";
      setAuthenticated(name);

      if (hasCompletedProfile(profile)) {
        router.replace("/");
      } else {
        router.replace("/signup?complete=1");
      }
    } catch (err) {
      setError(getAuthErrorMessage(err));
    } finally {
      setLoading(false);
    }
  }, [intent, router, refreshProfile]);

  const googleButtonLabel =
    intent === "signup" ? "Sign up with Google" : "Continue with Google";

  return {
    signInWithGoogleAccount,
    googleLoading: loading,
    googleError: error,
    clearGoogleError: () => setError(null),
    googleButtonLabel,
    googleAvailable: true,
  };
}
